const mattressProductVariants=[
  {id:'thin',name:'薄款绗缝垫',hint:'轻薄夹棉 · 细浅绗缝 · 窄平包边',spec:'床垫类别：1张薄款绗缝垫，约1～2厘米轻薄夹棉，细浅菱格绗缝、窄平包边，平铺承托，柔软可轻掀垫角；不是厚弹簧床垫或床笠。'},
  {id:'padded',name:'加厚床褥垫',hint:'柔软加厚 · 方格绗缝 · 可压缩边缘',spec:'床垫类别：1张加厚软床褥垫，约4～6厘米柔软可压缩填充，宽方格绗缝、缝处压低、圆润窄包边，平铺承托；不是硬床垫或被芯。'},
  {id:'foam',name:'乳胶 / 海绵垫',hint:'低矮立体 · 连续短侧围 · 支撑形态',spec:'床垫类别：1张乳胶或海绵结构垫，约6～9厘米均匀低矮芯层，连续布套、短侧围和窄包边，浅波浪压线；不生成厚弹簧床垫或内部剖面。'}
];
function currentMattressVariant(){return mattressProductVariants.find(v=>v.id===state.mattressVariant)||mattressProductVariants[0]}
function mattressSpecification(){return currentMattressVariant().spec}
const mattressVariantPanel=document.createElement('section');mattressVariantPanel.id='mattressVariantPanel';mattressVariantPanel.className='set-variant-flyout quilt-variant-flyout mattress-variant-flyout';mattressVariantPanel.hidden=true;mattressVariantPanel.setAttribute('aria-labelledby','mattressVariantTitle');
mattressVariantPanel.innerHTML='<div class="set-variant-heading"><div><h2 id="mattressVariantTitle">床垫</h2><p>选择垫层结构 · 默认薄款绗缝垫</p></div><button type="button" class="set-variant-close" aria-label="收起床垫分类">×</button></div><div class="set-variant-options"><h3>常见款式</h3><div class="set-variant-grid" role="group" aria-label="床垫款式"></div></div><div class="set-variant-footer"><span id="mattressVariantSelected"></span><button type="button" class="set-variant-done">完成选择</button></div>';
document.body.append(mattressVariantPanel);
function renderMattressVariantControl(){const trigger=document.querySelector('[data-product="mattress"]');if(trigger){trigger.classList.add('has-mattress-variants');trigger.setAttribute('aria-expanded',String(!mattressVariantPanel.hidden));trigger.setAttribute('aria-controls','mattressVariantPanel');trigger.title=currentMattressVariant().name+' · 点击展开床垫款式';renderChosenProductLabel(trigger,'床垫',currentMattressVariant().name);}if(state.product==='mattress'){$('partsHint').textContent='1 张'+currentMattressVariant().name+' · '+currentMattressVariant().hint;document.querySelector('.group-angles .group-purpose').textContent=currentMattressVariant().name+'构图 · 可多选 · AI 示例';}mattressVariantPanel.querySelector('#mattressVariantSelected').textContent='已选：'+currentMattressVariant().name;}
function closeMattressVariants(returnFocus=false){mattressVariantPanel.hidden=true;renderMattressVariantControl();if(returnFocus)document.querySelector('[data-product="mattress"]')?.focus()}
function placeMattressVariants(){placeProductSubmenu(mattressVariantPanel,document.querySelector('[data-product="mattress"]'),590);}
function selectMattressVariant(id){if(state.busy||state.product!=='mattress'||!mattressProductVariants.some(v=>v.id===id))return;(state.productVariantChoices??={}).mattress=true;state.mattressVariant=id;mattressVariantPanel.querySelectorAll('[data-mattress-variant]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mattressVariant===id)));renderMattressVariantControl();renderSelections();if(typeof closeMattressVariants==='function')closeMattressVariants(true);}
function openMattressVariants(){if(state.busy||state.product!=='mattress')return;const grid=mattressVariantPanel.querySelector('.set-variant-grid');grid.replaceChildren();for(const item of mattressProductVariants){const b=document.createElement('button');b.type='button';b.className='set-variant-option mattress-variant-option';b.dataset.mattressVariant=item.id;b.setAttribute('aria-pressed',String(currentMattressVariant().id===item.id));const picture=document.createElement('span');picture.className='mattress-variant-preview mattress-variant-preview-'+item.id;picture.setAttribute('role','img');picture.setAttribute('aria-label',item.name+'AI 结构示例');const name=document.createElement('strong');name.textContent=item.name;const hint=document.createElement('small');hint.textContent=item.hint;b.append(picture,name,hint);b.addEventListener('click',()=>selectMattressVariant(item.id));grid.append(b)}mattressVariantPanel.hidden=false;placeMattressVariants();renderMattressVariantControl();}
mattressVariantPanel.querySelector('.set-variant-close').onclick=()=>closeMattressVariants(true);mattressVariantPanel.querySelector('.set-variant-done').onclick=()=>closeMattressVariants(true);
document.addEventListener('click',e=>{const product=e.target.closest('[data-product]');if(product&&!state.busy){if(product.dataset.product==='mattress'){if(mattressVariantPanel.hidden)openMattressVariants();else closeMattressVariants()}else closeMattressVariants();renderMattressVariantControl();return;}if(e.target.closest('#resetBtn')&&!state.busy)state.mattressVariant='thin';if(!mattressVariantPanel.contains(e.target))closeMattressVariants();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!mattressVariantPanel.hidden)closeMattressVariants(true);if(e.key==='ArrowDown'&&e.target.closest('[data-product="mattress"]')&&!state.busy){e.preventDefault();openMattressVariants();mattressVariantPanel.querySelector('[aria-pressed=true]')?.focus();}});
window.addEventListener('resize',()=>closeMattressVariants());window.addEventListener('scroll',e=>{if(!mattressVariantPanel.contains(e.target))closeMattressVariants()},{passive:true,capture:true});
new MutationObserver(renderMattressVariantControl).observe($('products'),{childList:true});new MutationObserver(()=>{if(state.busy)closeMattressVariants();renderMattressVariantControl()}).observe($('generateBtn'),{attributes:true,attributeFilter:['disabled']});renderMattressVariantControl();
